<template><main class="auth-page"><div class="auth-visual"><img :src="visualImage || '/images/hero.jpg'" alt="الإلكترونيات والأجهزة المنزلية"/><div><span>Electronics & Home</span><h2>كل اختياراتك<br>محفوظة ومستنياك</h2></div></div><div class="auth-panel"><NuxtLink to="/" class="brand">Electronics & Home</NuxtLink><div class="auth-box"><h1>{{ title }}</h1><p>{{ subtitle }}</p><slot/></div></div></main></template><script setup lang="ts">defineProps<{title:string;subtitle:string;visualImage?:string | null}>()</script>
<style>.auth-page{min-height:calc(100vh - 118px);display:grid;grid-template-columns:1fr 1fr}.auth-visual{position:relative;overflow:hidden}.auth-visual img{width:100%;height:100%;object-fit:cover}.auth-visual:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(13,46,38,.8),transparent)}.auth-visual>div{position:absolute;z-index:2;bottom:50px;right:50px;color:#fff}.auth-visual>div span{font-weight:800}.auth-visual h2{font-size:2.5rem;line-height:1.3;margin:7px 0}.auth-panel{padding:34px 9%;display:flex;flex-direction:column}.auth-box{width:min(440px,100%);margin:auto}.auth-box h1{font-size:2.2rem;margin:0}.auth-box>p{color:var(--muted);margin:6px 0 25px}.auth-form{display:flex;flex-direction:column;gap:16px}.auth-form .btn{width:100%;margin-top:5px}.auth-form>p{text-align:center;color:var(--muted)}.auth-form a{color:var(--green);font-weight:700}.label-row{display:flex;justify-content:space-between}.sent-message{background:#e4f0e8;color:var(--green);padding:16px;border-radius:12px}.back-link{text-align:center}@media(max-width:750px){.auth-page{grid-template-columns:1fr}.auth-visual{display:none}.auth-panel{min-height:75vh;padding:28px 20px}}</style>
